"use strict";(globalThis.webpackChunk_8x8_developer_docs=globalThis.webpackChunk_8x8_developer_docs||[]).push([[1770],{1612:e=>{e.exports=JSON.parse('{"id":"2026-09-02-webhook-callback-urls-https","date":"2026-09-02","products":["Connect","APIs"],"product":"Connect","channel":"","changeType":"Changed","title":"Webhook and callback URL sample values updated to HTTPS","excerpt":"Sample URL values across the SMS and Business Messaging (Chat Apps) API documentation \u2014 webhook configuration, dlrCallbackUrl, delivery-receipt callback overrides, and rich-content URL fields \u2014 now use https://example.com instead of http://example.com, so the examples no longer read as an endorsement of plain HTTP for\u2026","hasArticle":true,"bodyHtml":"<p>Sample URL values across the SMS and Business Messaging (Chat Apps) API documentation \u2014 webhook configuration, <code>dlrCallbackUrl</code>, delivery-receipt callback overrides, and rich-content URL fields \u2014 now use <code>https://example.com</code> instead of <code>http://example.com</code>, so the examples no longer read as an endorsement of plain HTTP for callback URLs.</p>\\n<p>The OAuth token endpoint description on the webhook configuration endpoints has also been clarified: the token endpoint URL <strong>must use the <code>https</code> scheme</strong>; <code>http</code> URLs are rejected.</p>\\n<h2>Read more</h2>\\n<ul>\\n<li><a href=\\"/connect/reference/add-webhooks-1\\">Create or Replace webhooks (Business Messaging)</a></li>\\n<li><a href=\\"/connect/reference/add-webhooks-2\\">Create or Replace webhooks (SMS)</a></li>\\n</ul>\\n"}')}}]);